args.sparql:
SELECT DISTINCT ?director ?directorLabel ?birthPlace ?birthPlaceLabel WHERE {
  dbr:Rufus_Jones_for_President (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director (dbo:birthPlace|dbp:birthPlace) ?birthPlace . }
  OPTIONAL { ?director rdfs:label ?directorLabel FILTER (langMatches(lang(?directorLabel), "EN")) }
  OPTIONAL { ?birthPlace rdfs:label ?birthPlaceLabel FILTER (langMatches(lang(?birthPlaceLabel), "EN")) }
}

SELECT DISTINCT ?director ?birthPlace WHERE {
  dbr:Rufus_Jones_for_President (dbo:director|dbp:director) ?director .
  OPTIONAL { ?director (dbo:birthPlace|dbp:birthPlace) ?birthPlace . }
} LIMIT 10

